package org.apache.commons.io.function.adapter;

import java.util.Objects;
import java.util.stream.BaseStream;

import org.apache.commons.io.function.IOBaseStream;

/**
 * Abstracts an {@link IOBaseStream} implementation.
 *
 * Keep package-private for now.
 *
 * @param <T> The type of the stream elements.
 * @param <S> The type of the stream extending {@code IOBaseStream}.
 */
public abstract class IOBaseStreamAdapter<T, S extends IOBaseStream<T, S, B>, B extends BaseStream<T, B>> implements IOBaseStream<T, S, B> {

    /**
     * The underlying base stream.
     */
    private final B delegate;

    /**
     * Constructs an instance.
     *
     * @param delegate the delegate.
     */
    IOBaseStreamAdapter(final B delegate) {
        this.delegate = Objects.requireNonNull(delegate, "delegate");
    }

    @Override
    public B unwrap() {
        return delegate;
    }

}

