package org.apache.commons.io.function.adapter;

import java.io.IOException;
import java.util.Iterator;
import java.util.Objects;

import org.apache.commons.io.function.IOIterator;

/**
 * Adapts an {@link Iterator} as an {@link IOIterator}.
 *
 * @param <E> The type of the stream elements.
 */
public final class IOIteratorAdapter<E> implements IOIterator<E> {

    public static <E> IOIterator<E> adapt(final Iterator<E> delegate) {
        return new IOIteratorAdapter<>(delegate);
    }

    private final Iterator<E> delegate;

    private IOIteratorAdapter(final Iterator<E> delegate) {
        this.delegate = Objects.requireNonNull(delegate, "delegate");
    }

    @Override
    public boolean hasNext() throws IOException {
        return delegate.hasNext();
    }

    @Override
    public E next() throws IOException {
        return delegate.next();
    }

    @Override
    public Iterator<E> unwrap() {
        return delegate;
    }

}

