package org.apache.commons.io.function.adapter;

import java.util.Objects;
import java.util.Spliterator;

import org.apache.commons.io.function.IOSpliterator;

/**
 * Adapts an {@link Spliterator} as an {@link IOSpliterator}.
 *
 * @param <T> The type of the stream elements.
 */
public final class IOSpliteratorAdapter<T> implements IOSpliterator<T> {

    public static <E> IOSpliterator<E> adapt(final Spliterator<E> delegate) {
        return new IOSpliteratorAdapter<>(delegate);
    }

    private final Spliterator<T> delegate;

    IOSpliteratorAdapter(final Spliterator<T> delegate) {
        this.delegate = Objects.requireNonNull(delegate, "delegate");
    }

    @Override
    public Spliterator<T> unwrap() {
        return delegate;
    }

}

