package org.apache.commons.io.function.adapter;

import java.util.stream.Stream;

import org.apache.commons.io.function.IOStream;
import org.apache.commons.io.function.adapter.IOBaseStreamAdapter;

/**
 * Adapts an {@link Stream} as an {@link IOStream}.
 *
 * Keep package-private for now.
 *
 * @param <T> The type of the stream elements.
 */
public final class IOStreamAdapter<T> extends IOBaseStreamAdapter<T, IOStream<T>, Stream<T>> implements IOStream<T> {

    public static <T> IOStream<T> adapt(final Stream<T> delegate) {
        return delegate != null ? new IOStreamAdapter<>(delegate) : IOStream.empty();
    }

    private IOStreamAdapter(final Stream<T> delegate) {
        super(delegate);
    }

    @Override
    public IOStream<T> wrap(final Stream<T> delegate) {
        return unwrap() == delegate ? this : adapt(delegate);
    }

}
